// What's new: the additions coaches hear about in the weekly "What's new" email (api/weekly-features-email.js),
// newest first. Each entry is { date: "YYYY-MM-DD" (when it went live), area, title, detail } in plain words for
// a coach, not a developer. The email each Monday lists the entries from the seven days before it, grouped by
// area, and isn't sent at all in a week with none. Add an entry whenever something coaches or athletes will
// notice goes live. Plain JavaScript, usable from the dashboard (window.WHATS_NEW) and the email (require).
(function (root) {
  const AREAS = ["Phone app", "Program builder", "Coach Mode", "Dashboard"]; // the order they appear in the email

  const WHATS_NEW = [
    { date: "2026-11-11", area: "Dashboard", title: "Motion capture finds him in a wide shot, with others in it", detail: "A sprint filmed wide, with the athlete small in the frame and a coach or teammate beside him, used to fail with “couldn't find him in most frames.” Motion capture now looks closer when the whole frame shows no one, follows everyone in the clip, and keeps to the athlete who moves, never the coach kneeling next to him. A clip with one clear person in it is tracked as before. Wide clips take about a minute longer to analyze." },
    { date: "2026-11-11", area: "Dashboard", title: "A High School & Youth roster", detail: "Team Overview has a Pro Baseball | High School & Youth switch at the top. High School & Youth is a roster of its own, with its own location buttons and counts, and it stays out of the pro roster and the Sunday pro email. Athletes added or imported while it's showing go onto it, and the bulk bar's Move to Roster puts people on either one." },
    { date: "2026-11-11", area: "Phone app", title: "Testing shows the day's average", detail: "On Progress › Testing, a test with more than one rep (a 10-yard start, a broad jump) now shows that day's average next to the best." },
    { date: "2026-11-08", area: "Program builder", title: "Drag days to reorder them", detail: "Every day in the builder now has a ⠿ grip by its name: drag it onto another day and it takes that day's place. The ‹ › arrows by the day's ✕ move it one place at a time. Works in the Table view, and in Re-Ed, Speed and Throwing programs, where the day moves in every week. Days still called “Day 3” are renumbered to match." },
    { date: "2026-11-08", area: "Program builder", title: "+ Series on every strength day", detail: "Each day in a strength program now has its own + Series button (next to + Add row, or Add Block in the boxes view). It opens with that day already picked, so adding Core Strength 1 to Day 2 is two clicks. The week bar's + Series now sits beside the week name." },
    { date: "2026-11-08", area: "Program builder", title: "Saved series", detail: "Programs has a new Series tab: blocks of drills saved on their own (Core Stability 1, a T-Spine series, a band warm-up) to reuse in any program. Make one from scratch, or take it from a day of a program you already have. In the program builder, + Series on a week copies one into a day (strength, re-ed, speed or throwing; for re-ed and speed you pick the section), in that week or every week, or makes it a day of its own, say for an off day. The drills are copied in, so you can change them in that program without touching the saved series." },
    { date: "2026-11-08", area: "Phone app", title: "Drop In a Series", detail: "Coach tools has a new Drop In a Series button: pick a saved series and a date, and put it on your own plan or send it to athletes. It shows up in the app as its own card on that date, beside that day's workout, ready to log." },
    { date: "2026-11-08", area: "Coach Mode", title: "+ Series for the athlete you're looking at", detail: "In Coach Mode, + Series next to Print / PDF puts a saved series on that athlete's plan for a date, as its own card in their app." },
    { date: "2026-11-06", area: "Phone app", title: "Fixed: videos made on an iPhone wouldn't play", detail: "A bullpen or motion capture video made on an iPhone or iPad could come out as a file the phone itself wouldn't play (a play icon with a line through it). Those devices now record the video the way their camera does instead (it takes about as long as the video runs), so it plays and saves to the camera roll. Computers make it as before." },
    { date: "2026-11-06", area: "Phone app", title: "Phone-made videos sized to save", detail: "A bullpen video made on a phone is now 1080p at a modest bitrate (about a fifth of the size: a 4K one ran to half a gigabyte, more than an iPhone will share to Photos), so Save to camera roll can save it. If the phone still won't, what it said shows under the button. Videos made on a computer are as sharp as before." },
    { date: "2026-11-06", area: "Phone app", title: "Save to camera roll", detail: "Save video is now Save to camera roll, and it shows on iPads and on iPhones set to ask for the desktop site (they call themselves Macs, so they got Download again, which goes to Files). In the video queue, a bullpen whose video was made before has Get the video to save: it comes back from Drive, then Save to camera roll." },
    { date: "2026-11-06", area: "Dashboard", title: "Video queue: use a bullpen's video on file again", detail: "In the video queue, a bullpen that already has its video and clips no longer has to be uploaded again: choose the same video from your phone or computer (quickest, nothing uploaded, the saved clips kept) or Get it from Drive, then Check the clips, Make the video and Email the report. Replace it with a new video is still there for a new one." },
    { date: "2026-11-06", area: "Dashboard", title: "Made bullpen videos save to Google Drive", detail: "Every bullpen video made (the MP4 of each pitch with its numbers), from the queue or a bullpen's Export video, is now saved to the pitcher's folder in Google Drive straight away, shared by link, and kept on his bullpen (one vertical and one horizontal: making one again replaces it). The video bar links them, the queue has In Drive, and the report email links the made video first, then the whole bullpen as filmed. Save video to Photos is still there too." },
    { date: "2026-11-06", area: "Dashboard", title: "Make a queued video again", detail: "In the bullpen video queue, a pitcher whose video is made has Make it again (it says the new shape when you've switched between vertical and horizontal), and Make them again remakes every video made in the other shape." },
    { date: "2026-11-06", area: "Phone app", title: "Save video stays until it saves, and Open it", detail: "On a phone, Save video now stays on screen until the phone says the video was saved (closing the share sheet, or a share that fails, no longer counts as done), and a new Open it button opens the video in a tab of its own: Share there, then Save Video, puts it in Photos." },
    { date: "2026-11-06", area: "Phone app", title: "Save video puts it in Photos", detail: "Save video on a phone now hands the share sheet only the video (an iPhone leaves Save Video out when a title comes with it), so Save Video there puts it in Photos. Where a phone can't share it, the video goes to its downloads (an iPhone: Files › Downloads) and it now says so, with how to move it to Photos, instead of just Done." },
    { date: "2026-11-06", area: "Dashboard", title: "Undo for a bullpen's edited numbers", detail: "Every pitch › Edit numbers now has ↶ Undo and ↷ Redo for the numbers you change, and a ↺ under each column of the top row that puts TrackMan's own numbers back in just that column (say, a release height set wrong on every pitch), leaving the other edits alone." },
    { date: "2026-11-06", area: "Dashboard", title: "Bullpen video queue: several pitchers at once", detail: "Video queue (on the Bullpens tab, and Bullpen Video in the phone app's Coach tools) takes several pitchers in a row: pick each pitcher, import his TrackMan PDF or choose a bullpen on file, choose his video, and go on to the next. They're worked through one at a time: the pitches found, each cut from the leg lift, the video into Google Drive (shared by link) and the clips onto his bullpen. Then each has Check the clips, Make the video and Email the report (the PDF with his video's link), and Make every video makes them all, one after another. It runs while the page is open (on a phone, with the screen on)." },
    { date: "2026-11-06", area: "Dashboard", title: "Email a bullpen report, with the video link", detail: "A bullpen's PDF report box now emails it to the pitcher from your own address, the PDF attached: his email is filled in from his profile, with a CC, the subject and a message you can change, which has the link to his bullpen video in Google Drive (anyone with the link can watch it). Download the PDF is still there too." },
    { date: "2026-11-06", area: "Dashboard", title: "Match a bullpen video's clips to the pitches", detail: "Match clips to pitches (on a bullpen's video bar, and in the pitch player) puts the video's clips down the left in the order filmed beside TrackMan's pitches on the right in the order thrown. Tap a clip to watch it; move it up or down, delete one that isn't a pitch in the report, or put a gap where the video missed a pitch, with Undo and Redo. Nothing changes until Save the matching. It replaces the old a-pitch-earlier / a-pitch-later buttons." },
    { date: "2026-11-06", area: "Dashboard", title: "Fixed: bullpen video export stalling", detail: "Making a bullpen video could stop partway (2 of 18, say) and Cancel didn't stop it. The long video is now opened once for all its clips instead of once per pitch, nothing waits on the browser forever (a clip it stops playing is stepped through instead), and Cancel stops it within a second. Bullpen videos kept in Google Drive are also shared to anyone with the link as they upload, so the link can be sent to the athlete." },
    { date: "2026-11-06", area: "Dashboard", title: "Bullpen PDF report", detail: "A bullpen session has a PDF report button: a DST-branded report with the pitcher, date and facility under the DST logo, your coach's notes (typed in before it's made), the pitch types' numbers, the movement chart with his arm angle, the release point, the locations with the share in the zone by pitch type, and every pitch." },
    { date: "2026-11-06", area: "Dashboard", title: "Correct a bullpen's numbers by hand", detail: "Every pitch › Edit numbers: type a new number into any pitch's cell (velo, spin, tilt, IVB, HB, extension, release height and side, spin efficiency), or into the top row to set it for every pitch (or just the checked ones), say when TrackMan's extension is clearly off. TrackMan's own numbers are kept and marked * once changed, VAA is worked out again, and Put TrackMan's numbers back undoes it all." },
    { date: "2026-11-06", area: "Dashboard", title: "Spin efficiency estimated where TrackMan left it blank", detail: "TrackMan often leaves spin efficiency blank on a gyro slider, so its ball spun as pure side spin. Now a blank efficiency is estimated from how far the pitch moved for its spin and speed (marked ~), so a gyro slider spins like one, in the spin balls, the tables, the video export and the PDF report." },
    { date: "2026-11-06", area: "Phone app", title: "Bullpen Video from the phone", detail: "Coach tools has a new Bullpen Video: pick the pitcher, choose his TrackMan PDF (or a bullpen already on file), then one video of the whole bullpen filmed on the phone. Each pitch gets its own clip, from the top of the leg lift to 0.6 s after the ball reaches the plate (his release plus the pitch's flight from TrackMan's speed and extension), matched to the report's pitches in order. Tap any pitch to watch its clip, and move the clips a pitch either way if one is off. Save puts the video in Google Drive and the clips on his bullpen, so they play on the dashboard too, and Make the video exports the pitches with their TrackMan numbers to Photos." },
    { date: "2026-11-06", area: "Dashboard", title: "Phone bullpen video cut from the leg lift", detail: "A bullpen video from a phone (Video › Phone on a bullpen) is now cut the same way: each pitch from the top of the leg lift to 0.6 s after the ball reaches the plate, found with the pose model, instead of a fixed stretch around the motion. Where the pitcher isn't clear in the picture, that pitch keeps a clip around its motion." },
    // ---- week of Nov 2 - 8, 2026 ----
    { date: "2026-11-05", area: "Dashboard", title: "Sprint Assessment: what each number means", detail: "Every number in a Sprint Assessment report has its label underlined with dots: hover over it (or tap it on a phone or tablet) for what it means, from F0, V0, max power and tau to each segment column, the video columns (first step, first 3 steps, foot clearance, contact), the load-velocity numbers and training zones, the ratings, and the CMJ columns. Tap again, or anywhere else, to close it." },
    { date: "2026-11-05", area: "Dashboard", title: "Sprint Assessment", detail: "A new Sprint Assessment under each athlete's Movement tab (and in Coach Mode's Motion Capture and the phone app's Coach › Motion Capture, so it can be done from a phone or tablet at the track). Type in each rep's timing gate times (10, 20, 30, 40 yd, or any gates you set) and the steps to each gate, any resisted sprints (the sled load with a time over a distance, or the speed a radar or 1080 measured), and link his sprint videos. It gives the best rep's segments (time, speed, share of top speed, steps, step length and rate), a force-velocity profile from the splits (F0, top speed, max power, projected 10-60 yd times; the delay between his first move and the first beam is fitted), a load-velocity profile from the sled reps (his unloaded speed, the load that would stop him, and the loads for each training zone), what his videos show (first step, first 3 steps, foot clearance, top speed in the clip), and the change since his last assessment. What it says rates the start, acceleration, transition and top speed (strong, middle or needs work, against our other athletes once five are tested, or the usual range), with basic ways to improve what needs it and keep what's strong (using his own sled loads), and the CMJ numbers that go with each, his latest beside our other athletes' and his jump before." },
    { date: "2026-11-05", area: "Dashboard", title: "Sprint motion capture: steps on the track, shadow runner, clearance", detail: "Sprint motion capture now measures the distance covered in the first 3 steps and the time to the third, and foot clearance in swing (how high the foot travels off the ground). On the track: type the yard line of a cone or gate in the picture and click where it stands, and every step gets its yard line, so clips from a few camera spots (0-10, 10-20…) add up to his steps at each gate in Sprint Assessment. Shadow runner: pick any saved sprint of the same start (his own or another athlete's) and its skeleton runs beside him on the video in light blue, starting together, at true size and distance, with the gap between them shown. Saved sprints can be re-run for the new numbers." },
    { date: "2026-11-05", area: "Dashboard", title: "Body Weight on Performance Metrics", detail: "The Performance Metrics tab has a Body Weight panel of the athlete's pre-lift weigh-ins (Pre Weight on their phone's Program page), in the tab's date range: the latest, the 7-day average, the change week over week and across the range, a graph of every weigh-in with its 7-day average, and each entry with its change from the one before and who logged it. It picks up weigh-ins made on the phone since the dashboard opened." },
    { date: "2026-11-05", area: "Phone app", title: "Body weight on Progress", detail: "The Progress tab has a Body weight section of their own weigh-ins (Pre Weight on the Program page): the latest, the 7-day average and the change from the week before, a graph over 90 days, 6 months, a year or all time, and their last seven weigh-ins with the change from the one before." },
    { date: "2026-11-05", area: "Dashboard", title: "Fixed: \"Failed to load the dashboard\" after an edit", detail: "Adding a block to a periodization chart (and now and then other edits) could replace the whole dashboard with \"Failed to load the dashboard\" until a refresh, though the change had saved. A small, harmless browser notice was being treated as the dashboard failing to start. Now only a dashboard that really can't start shows that; anything else stays on screen, and if a part of a page ever does fail it says what went wrong, with Try again, instead of blanking the page." },
    { date: "2026-11-03", area: "Dashboard", title: "Off slot: movement against the arm angle, in rarity and comps", detail: "Every pitch now has Off slot: how far its movement turns off the line of the pitcher's arm angle on the movement chart, in degrees from whichever end of the line it's nearer (+ more vertical than his slot gives: ride on a fastball, depth on a curveball; − more horizontal: run on a changeup, sweep on a slider). Hitters read the arm, so a pitch that doesn't move the way the arm looks is harder to pick up. It counts toward Rarity (and is named when it's what stands out), toward comp Match along with arm angle itself, and has its own percentile beside Arm angle's; the comps and Statcast tables show it. Bullpen pitches now have an arm angle too (marked ~, from the release and his height), so arm angle counts in their rarity, not just MLB games'. The Statcast tab's seasons go back to 2020, and its Movement chart has a button for each year." },
    { date: "2026-11-03", area: "Dashboard", title: "Arm angle on the movement charts", detail: "A bullpen's Movement chart has a dotted line along the pitcher's arm angle, labeled with it: worked out from the session's release height and side and his height (the shoulder at 70% of it), the way Baseball Savant gives arm angle. A pitch thrown straight off his hand moves along it, and fastballs usually sit near it. The Statcast tab has a new Movement chart too, each pitch at its season average, with Savant's own measured arm angle. Players linked to MLB get their height from MLB; for others, add it to the profile (6'2\" is assumed until then)." },
    { date: "2026-11-03", area: "Dashboard", title: "Vertical video exports play on iPhones", detail: "Vertical (phone) exports of bullpens and motion capture are now stored the way an iPhone stores its own portrait video, so they play in Photos, Messages and the rest (a tall high-resolution video stored standing up wouldn't play on an iPhone). Made on a phone, the video ends with a Save video button: tap it, then Save Video in the share sheet, and it's in Photos (iPhones only open the share sheet straight after a tap, and making a video takes longer than that)." },
    { date: "2026-11-03", area: "Dashboard", title: "Motion capture: click a saved session to open it", detail: "In motion capture's Saved sessions, a click anywhere on a session's row opens its report: no more scrolling across to Open report. Its Re-run, Re-track and ✕ buttons still do just their own thing." },
    { date: "2026-11-03", area: "Dashboard", title: "Jump motion capture closer to the force plate", detail: "Jump height from video now matches how a force plate measures it: the time in the air allowing for landing with the hips lower than at takeoff (knees and ankles already bending), which made flight-time heights read inches high. Takeoff and landing are placed between frames, each foot's ground is taken right before takeoff and after landing, and a far foot hidden behind the near leg no longer counts (it looked planted through the jump). Time to takeoff starts where the dip really starts, not a slow settle before it. On Dalton Hill's CMJ the video now reads 17.3 in against the plate's 17.1. The flight-time height is still shown beside it. Saved jumps show as older: Re-run updates them." },
    { date: "2026-11-03", area: "Program builder", title: "Periodization: notes on days and weeks", detail: "A player's periodization chart has a Notes row under the weeks for anything that changes the plan: a wedding, a trip, a showcase. Click a week in it for a note on that week, then pick Whole week or just the days (Fri, or Shift-click to run it Fri to Sun), or set the dates. Notes show as yellow tags on the chart and are listed under it, with the week and dates, on the Player Plan, the profile, the team report and the printed plan. They stay on their dates if week 1's start moves." },
    { date: "2026-11-03", area: "Coach Mode", title: "Exercise videos: film or upload, and replace", detail: "The camera on an exercise with no video (Coach Mode, or a coach's own phone link) now asks: Film it, or Choose a video already on the phone or computer. The clip goes straight into the exercise library as filmed; one too long or big for the library (over 50 MB) is made smaller on the phone first, so it still fits. To re-record one, open the exercise's video and tap Replace video (coaches only): film or choose the new one and it takes the old one's place everywhere the exercise is programmed, for every athlete." },
    { date: "2026-11-03", area: "Dashboard", title: "Motion capture fills in height and weight", detail: "Motion capture now starts with the athlete's height from their profile and their most recent weight: whichever is newest of a force plate test (CMJ), a body comp scan, or a pre-weight logged in their program (it says which). A height typed in for someone whose profile has none is saved to the profile, so it's only entered once. Profiles have a Height (in) box under the ✎, filled in from MLB for linked players." },
    { date: "2026-11-03", area: "Program builder", title: "Re-education programs with several days a week", detail: "A re-education program can now have different days through the week (Mon T-Spine, Tue Hips, Thu T-Spine, Fri Hips…): + Add day in the re-ed builder, and each day shows as its own day in the athlete's app, a week of the program for each week on the plan. A re-ed program of one day still works as before: done every day for as long as its phase runs." },
    { date: "2026-11-03", area: "Dashboard", title: "Bullpen video kept in Google Drive, any size", detail: "Bullpen video added from now on goes to the company's Google Drive (the DST Dashboard Content shared drive, a folder per athlete) instead of the dashboard's own storage, so a long or high-resolution video of any size can be kept. It uploads in pieces with a percentage showing, picks up where it left off if the connection drops, and stays private: only coaches signed in to the dashboard can watch it. Video added before stays where it is and plays as always; video taken off a bullpen goes to the shared drive's trash for 30 days." },
    { date: "2026-11-02", area: "Dashboard", title: "Throwing Program tab", detail: "Under Pitching, the Throwing tab is now called Throwing Program, and so is Hitting / Fielding's Throwing Progression tab." },
    { date: "2026-11-02", area: "Dashboard", title: "Export videos with the numbers beside them", detail: "Bullpen and motion capture videos can now be exported as an MP4 with a data panel, the athlete's name and the DST logo in the bottom right: Horizontal (16:9, the panel on the right) for a computer or TV, or Vertical (9:16, the panel along the bottom) for a phone. Bullpens › Export video plays the pitches you pick (by type, or by number), each with its TrackMan numbers, the ball spinning as Pitch Design draws it (for Edgertronic video) and where its movement sits among the session's, with a title card and ½ or ¼ speed if wanted. Motion Capture › Export horizontal / vertical plays the clip with its skeleton, the moment (foot strike, release…) and his numbers. Videos are only made when you ask, on your phone or computer, and go straight to your downloads (a phone's share sheet saves them to the camera roll); nothing is stored on the dashboard. Bullpen video can now come from a phone too: pick Phone before Add video, and one long recording of the whole bullpen is split at each delivery. The video keeps its full quality: the file is made as big as it needs to be (1440p or 4K) so an Edgertronic or iPhone clip shows at its own resolution, never shrunk, and Fill the frame zooms it to fill its area. A video of any size can be made into one without uploading it: choose the file under Add video, then Export without uploading." },
    { date: "2026-11-02", area: "Dashboard", title: "Bullpens: export to CSV", detail: "Pitching › Bullpens has Export CSV beside Import TrackMan PDF: every pitch of the session open, a row each (date, pitch number and type, velo, spin, tilt, spin efficiency, IVB, HB, extension, release height and side, and the rest TrackMan reported), ready for Google Sheets or Excel. Export all sessions puts every bullpen of his in one file, oldest first. Pitches taken out of the report are included and marked." },
    { date: "2026-11-02", area: "Program builder", title: "Add a row in the middle of a day", detail: "In the Table view, each row's label (A1, A2, B1…) has a + under it that adds a row straight after it in the same block: after A2 it's A3, even with B, C and D below, and anything after it in the block moves down. Click the new row's label to make it a block of its own instead. (The Boxes view's Add A3 button under each block does the same.)" },
    { date: "2026-11-02", area: "Coach Mode", title: "Motion Capture in Coach Mode, with a roster", detail: "Coach Mode has a Motion Capture button. It opens a roster for one movement (Sprint to start; Jump, Hitting, Pitching or Movement Screen in one tap): everyone on the board, or every active athlete (at the location picked on the left), with whether they've been captured, how many times, when last and their latest numbers. Narrow it to Captured or Not yet to see who still needs filming, and pick a start type or jump to check just that one (who has a base-stealing start on video, say). Tap a name to film them, or to open, compare and send their saved captures; Back returns to the roster." },
    { date: "2026-11-02", area: "Dashboard", title: "Motion capture: compare side by side, by curves and by numbers", detail: "Any saved motion capture (sprints and jumps especially, and swings and deliveries too) can be compared with the athlete's own past tests and with other athletes': open a report and click Compare: skeletons, curves, numbers. Pick his other sessions and/or other athletes (all, or the ones you choose, by date), then look at them four ways: 3D overlay (all the skeletons on one, pinned at a joint if wanted), Side by side (each skeleton in its own box, same height and facing the same way, moving together with the video), Curves (his hip speed, knee bend and the rest with each other session's on the same chart, lined up by the moments of the movement or by time) and Numbers (his results beside each session's, with their mean or median and the difference). A sprint is compared with the same start type and a jump with the same kind of jump." },
    { date: "2026-11-02", area: "Dashboard", title: "Pitch Design: comps from related pitches", detail: "Another pitcher's pitch, in Pitch Design, now searches the pitch's neighbors as well as its own kind, so a pitcher changing a pitch's style can model it: a slider can copy a sweeper, slurve or cutter (Hayden Wesneski's slider is a sweeper to Baseball Savant), a curveball a knuckle curve or slurve, a changeup a splitter (and the other way round), a four-seam a sinker. Each one still says what Savant calls it, and his own kind is listed first." },

    // ---- week of Oct 26 - Nov 1, 2026 ----
    { date: "2026-11-01", area: "Dashboard", title: "Pitch Design: another pitcher's pitch as the design", detail: "In Pitch Design, the Designed side can now be another pitcher's real pitch: switch it from Custom to Another pitcher's and search any MLB pitcher who threw that pitch (Baseball Savant) or any DST athlete with it in his bullpens. His pitch on the left, theirs on the right, with the table, movement chart, comps and spinning balls comparing them; a pitcher of the other hand is mirrored to his (or not, with the checkbox). Start custom from this puts their velo, spin direction, efficiency and seam effects on the dials to shape from, and a goal saved this way says what it's modeled on." },
    { date: "2026-11-01", area: "Dashboard", title: "Pitch Design: new pitches and grips to try", detail: "Pitch Design can now design a pitch he doesn't throw yet: + New pitch offers a four-seam, sinker, cutter, bullet (gyro) slider, sweeper, vertical slider, curveball, knuckle curve, changeup, kick change, splitter or split change, starting from a typical one of its kind with its velo set off his fastball, then shaped with the dials like any other (comps, rarity and seam effects included). Every pitch now shows three grips to try: how to hold it, what it does, cues, a fix if it isn't working, and links to Driveline's articles, reporting on the kick change and split-change, and video and image searches. Add our own photo of a grip with 📷 (every pitcher sees it), and Use this grip puts it and its cues on the goal and the printed plan." },
    { date: "2026-10-31", area: "Program builder", title: "Make a series from drills already in a program", detail: "In re-education, speed and throwing programs (Table view), highlight a few drills (drag across their rows, or click one and Shift+click another) and right-click: Make a series… names them (T-Spine Series, say) and gathers them together where the first one is. Take out of their series unlinks drills you don't want in one, leaving the rest of the series together. Right-click a single drill to do it to just that one. Ctrl+Z undoes either." },
    { date: "2026-10-31", area: "Dashboard", title: "Bullpen report: add and remove modules", detail: "The bullpen report's modules can now be added and taken off, not just moved and resized: + Add a module (top right) and the ✕ on each. New modules, matching TrackMan's practice report: a Tilt plot (every pitch on the clock, measured or from its movement, farther out for more spin), a Location heatmap (the share of pitches in each part of the zone and the corners), Pitch location (every pitch numbered where it crossed the plate), Ranges by pitch type (lowest to highest of velo, spin, IVB, HB, extension or release height, with the average), and By session (each type's velo, spin, IVB and HB session to session). The set and arrangement are kept per coach." },
    { date: "2026-10-31", area: "Program builder", title: "The assessment beside the program", detail: "Building a program, pull out the athlete's biomechanical assessment from the Assessment tab on the right edge of the Programming page: a drawer with what needs attention, the body regions flagged, the movement tests (fails first, in red), isolated ROM left and right beside each target, the overhead squat's findings and performance testing, without leaving the program. Pick any of his dated assessments; it opens on the latest, and stays open as you work if you leave it open." },
    { date: "2026-10-30", area: "Dashboard", title: "Hitting motion capture: bat tracking", detail: "Wrap 2 to 3 inches of bright tape (green or pink is best) around the end of the barrel, choose its color under Bat tape, and the swing report tracks the bat as well as the body: bat speed at the sweet spot at contact, time to contact, swing length, rotational acceleration, peak bat angular velocity, vertical bat angle and attack angle, with the bat and the barrel's path drawn over the video and its speed and turn on the curves. A second camera behind measures the barrel's depth; with one camera it's estimated from the bat's length (enter it). Contact is then the barrel at its fastest, which sharpens every timing in the swing." },
    { date: "2026-10-30", area: "Dashboard", title: "Movement Screen by video, into the biomechanical assessment", detail: "A Movement Screen tab under Assessments (and in the phone's Coach › Motion Capture) measures the assessment's tests from a short clip each: the overhead squat from the front (knee valgus each side, hip shift, depth) and the side (trunk and shin, arms falling forward, forward head, heel rise), active and passive straight leg raise, hamstring 90/90, shoulder flexion, shoulder ER and IR at 90/90, elbow extension and flexion, hip IR and ER seated or prone, the modified Thomas test, prone hip extension, ankle dorsiflexion, single-leg balance and seated thoracic rotation. It finds the end of range in the clip (End range here moves it), and Send to assessment fills the results into his biomechanical assessment from the last two weeks, or a new one: the ROM numbers, pass or fail with the reading in the notes, and the overhead squat checklist. Jump and sprint motion capture can send the CMJ height and 10-yard start to Performance Testing the same way." },
    { date: "2026-10-30", area: "Dashboard", title: "Motion capture: inferred metrics and the force plate", detail: "Motion capture now estimates what video can't see directly, each labeled an estimate. Pitching: peak ground forces (drive before foot strike, vertical and braking after it, in body weights and pounds), an arm stress checklist (arm position at foot strike, early trunk rotation, sequence, front leg, glove-side lean) and velo indicators against their usual ranges. Hitting: ground forces, bat speed and exit velo potential from hand speed. Sprint: speed at every step, splits at 1, 2, 3, 5, 10, 15 and 20 meters, and for a start a force-velocity profile (max speed, max horizontal force and power) with projected 10, 30, 40 and 60-yard times, or time to second base from a lead. Jump: takeoff velocity, peak power (Sayers), average force and power through the up phase, takeoff and landing forces, and the force plate jump of the same kind closest in date beside it. Weight comes from his latest body comp scan (or the force plate) and can be changed." },
    { date: "2026-10-30", area: "Dashboard", title: "Motion capture for hitting, sprinting and jumping", detail: "Motion capture now does more than pitching. Hitting (Hitting / Fielding › Motion Capture): a swing from the open side, with an optional camera behind, measures stride, load and foot plant to contact timing, front leg block, trunk tilt, hip-shoulder separation, pelvis and trunk speeds and the kinematic sequence, head movement and hand speed. A new Movement tab, for every athlete, has Sprint and Jump. Sprint: a linear start, a base-stealing start (crossover or jab, first foot to move), a 40-yard three-point start, or max velocity, with the first move and first step, time to 1 and 2 meters, every step's contact and flight time, step length and rate, speed, shin and trunk angles at touchdown, foot ahead of the hips and knee lift, step by step. Jump: a countermovement jump, broad jump, or single-leg jump on either leg, with jump height from flight time, countermovement depth and timing, RSI-modified, angles at the bottom and takeoff, landing knee bend, and broad jump distance and takeoff angle. Each has its own filming tips, and the playback, fix points, 3D skeleton and comparisons, report, email and re-run that pitching has. On the phone, Coach › Motion Capture asks which movement first." },
    { date: "2026-10-30", area: "Dashboard", title: "Pitch Design: seam-shifted wake from MLB pitches", detail: "Pitch Design now predicts how a pitch's seam effects (the seam-shifted wake: how far it moves off where its spin alone would send it) change with the design. It learns from every MLB pitch of the type that season, comparing Baseball Savant's measured spin direction with where each pitch went, and changes his pitch's own seam effects by what MLB pitches with a similar spin direction, efficiency and velo show: a sinker given more gyro picks up the extra run and sink sinkers like it have. The seam effects slider and handle are gone; the table shows the seam effects now, as designed, and the change." },
    { date: "2026-10-30", area: "Dashboard", title: "Motion capture: re-run saved sessions", detail: "As the motion capture analysis improves, saved sessions can catch up. Saved sessions now shows which were worked out with an older analysis, and Re-run (one session, all of a pitcher's, or every pitcher's at once) works their numbers, curves and sequence out again with the latest analysis in seconds. Re-track runs a session's kept video through the pose model again first, for when the tracking itself improves. Moments set by hand, fixed points and settings carry over either way." },
    { date: "2026-10-30", area: "Dashboard", title: "Motion capture: 3D skeleton and comparisons", detail: "A motion capture report can now show the skeleton on its own in 3D: drag it (or use the Turn, Tilt and Roll dials) to see the delivery from the open side, behind, the plate, the glove side or overhead, and it moves with the video. Lay other deliveries over it: his own other sessions, other pitchers' (all of them or the ones you pick, same hand only if you like), within a date range, each in its own color or as their mean or median. They line up by the moments of the delivery (or the time from foot strike or release), can be pinned at a joint such as the back heel, lefties can be mirrored to match a righty, and everyone can be scaled to the same height. A table compares his lead knee, elbow, shoulder abduction, trunk tilt and lean, separation and stride with the group's at the frame showing. Video and Skeleton checkboxes take either off the picture and put it back." },
    { date: "2026-10-30", area: "Dashboard", title: "Motion capture report: print, PDF or email", detail: "Every motion capture report now has Print, Save as PDF and Email to athlete: a report with his four key moments, the kinematic sequence and its timing, every number beside its usual range (outside it in amber), the curves through the delivery, the 3D skeleton and its comparison when it's open, and your notes. Email sends it from your own address with the PDF attached, to the athlete or anyone you add. It works from the Coach tab on the phone too." },
    { date: "2026-10-30", area: "Dashboard", title: "MLB pitches break the right way", detail: "Baseball Savant gives a pitch's horizontal break without saying which side, so MLB curveballs, sliders, sweepers and cutters were being treated as breaking to the arm side. They now break to the glove side (the side comes from the way Savant says each pitch moves), which corrects the MLB comps, percentiles and rarity for those pitches, and Pitch Design: making an MLB curveball more 12-6 now drops it, as it should." },
    { date: "2026-10-30", area: "Dashboard", title: "Motion capture: the elbow's early peak as depth", detail: "When the elbow extension curve shows an early first peak (the forearm turning toward or away from the camera, which looks like straightening from the side), the report now treats it as depth, not extension, and starts the elbow line at the dip after it, so only the real extension into release shows. A checkbox under the kinematic sequence turns it off, and the choice saves with the session." },
    { date: "2026-10-30", area: "Dashboard", title: "Motion capture: playback, synced sequence, Edgertronic", detail: "Motion capture reports now play the video at 0.25× to 1.5× with the skeleton over it, and a line on the kinematic sequence follows along: pause anywhere to see that moment on the curves, or click the curves to jump the video there. There's an Edgertronic setup for high-speed video (enter its frame rate), and the tracking now looks at every frame fresh, on a close crop around the pitcher, so the shoulder, elbow and wrist keep up through arm acceleration instead of lagging." },
    { date: "2026-10-30", area: "Dashboard", title: "Motion capture: fix the dots, tighter tracking, timing check", detail: "Motion capture now uses the larger, more accurate pose model and drops the short glitches where it loses a fast arm. On any report, Fix points lets you drag a dot that missed its joint (shoulder, elbow, wrist, hip, knee, ankle) to the right spot; the frames around it follow, the numbers update, and the fixes save with the session. Recorded at can be changed on the report, and if foot strike to release comes out impossibly quick it says the clip was most likely 120 fps (the iPhone's usual Slo-Mo) and switches it in one tap." },
    { date: "2026-10-30", area: "Dashboard", title: "Pitch rarity, better comps, grips", detail: "Every pitch in the comps (bullpens, Statcast, and the designed pitch in Pitch Design, beside its rarity now) has a Rarity score: how unusual it is among MLB pitches of its type thrown with the same hand, across velo, break, spin and its efficiency and direction, release height and side, extension, VAA and arm angle, with what makes it stand out. Comps now also match on release side and VAA, show the closest five, and each MLB comp has a 🔍 to search for his grip and a 📷 to add a screenshot of it, which then shows for everyone." },
    { date: "2026-10-30", area: "Dashboard", title: "Motion capture: reports on any device, better moments, delete", detail: "Saved motion capture sessions now open as the full report anywhere (the skeleton, the kinematic sequence, every number), from the phone or the dashboard; keep the video too and it replays under the skeleton. Foot strike is now found once the front foot has finished its stride (a foot that slides out low fooled it before), release and max layback are looked for where they belong, and each speed peak in its own window, so the elbow's is between max layback and release. Sessions can be deleted from the list." },
    { date: "2026-10-30", area: "Dashboard", title: "Motion capture: the kinematic sequence", detail: "Motion capture now shows the kinematic sequence: pelvis, trunk, upper arm and elbow extension speeds on one chart around foot strike and release, each peak marked, with a table of the peak speeds, when each comes after foot strike and before release, the trunk-to-pelvis speed gain, and whether they fired in order (hips, trunk, arm, elbow)." },
    { date: "2026-10-30", area: "Dashboard", title: "Motion capture for pitching mechanics", detail: "A new Motion Capture tab under Pitching: choose an iPhone or iPad video of a delivery (one camera on the open side, or two with one behind) and the dashboard finds his body in every frame, marks leg lift, foot strike, max layback and release, and measures stride, lead knee and block, trunk tilt and lean, elbow and shoulder at foot strike, arm slot, hip-shoulder separation, pelvis and trunk rotation speeds and their timing, and center-of-mass speed, each beside a usual range, with the skeleton drawn over the video and curves through the delivery. Tips for filming are built in, and sessions save to his profile." },
    { date: "2026-10-30", area: "Phone app", title: "Motion capture on your phone", detail: "Coaches: the Coach button on your app's bottom menu now has Motion Capture. Pick a pitcher (or a coach), then Film it now (the camera opens and the clip comes straight back) or choose a Slo-Mo clip from Photos (tips included), and get his mechanics in numbers right there, kinematic sequence and all. Sessions save to their profile on the dashboard, where coaches now have a Pitching tab too." },
    { date: "2026-10-30", area: "Dashboard", title: "Bullpens show progress on pitch design goals", detail: "Each bullpen now has a Pitch design goals section: for every pitch with a goal, how far its movement is from the goal, whether it's getting closer or moving away since his last bullpen, how much of a planned change has happened, or for a pitch being kept, whether it's holding its shape. Its velo, spin direction and efficiency show beside the goal's, with the distance to goal bullpen by bullpen." },
    { date: "2026-10-30", area: "Dashboard", title: "Pitch Design: shape the spin by hand", detail: "The designed ball in Pitch Design now has handles: drag the solid knob around the ring to turn the spin direction, the hollow one to set where the pitch really goes (seam effects), and the white knob on the spin axis in toward the middle for more gyro or out for more efficiency (or around to turn it). The dials and predictions follow along." },
    { date: "2026-10-30", area: "Dashboard", title: "Pitch Design goals and a printable plan", detail: "In Pitch Design, save a pitch as a goal: either a change (the pitch now and as designed) or \"maintain shape and qualities\" to keep it where it is. Goals show on the pitch chips and build a Pitch Design Plan on the same tab: for each pitch, still balls, the numbers now and the goal, a written summary of the change in plain words, and a notes box for cues. Print plan prints just that." },
    { date: "2026-10-30", area: "Dashboard", title: "Pitch Design", detail: "A new Pitch Design tab under Pitching: pick one of a pitcher's pitches (from his latest bullpen, all his bullpens, or his MLB season), then move its velo, spin direction, gyro versus efficiency and seam effects (drag, or − / + for fine steps; its spin rate stays as it is), and see the designed pitch spin beside the real one with its predicted IVB, horizontal break, total break and where it moves, plus an arrow on the movement plot from the old pitch to the new. Predictions come from the change in Magnus lift, scaled from the pitch's own measured break, and keep (or let you set) how far it moves off its spin from seam effects." },
    { date: "2026-10-30", area: "Dashboard", title: "Spinning balls: our own stamp, leather grain, flip the seams", detail: "The spinning balls now look like a game ball: \"★ Official ★ Dynamic Sports Training\" with Kevin Poppe's signature on the sweet spot, \"Pitching\" in script above the seam, and a navy plate with the DST logo below the other, all turning with the ball so you can follow the spin. The leather has a light pebble grain, and a new ⇋ Flip seams button mirrors the seams (the horseshoe swaps sides) without changing the spin." },
    { date: "2026-10-30", area: "Dashboard", title: "Extension in the comps, velo on the spinning balls", detail: "Extension now counts in the pitch comps (MLB extension from Baseball Savant, bullpen extension from TrackMan): it's part of the match, has its own percentile bar, and shows in every comps table and the MLB arsenal. The Pitching Assessment's Pitch Movement table has an Ext. column the TrackMan import fills in. Each spinning ball now shows the pitch's average velo, and the seams sit a little more open." },
    { date: "2026-10-30", area: "Dashboard", title: "Hitting / Fielding tab for position players", detail: "To match the pitchers' Pitching tab, everyone else's profile now has a Hitting / Fielding tab holding their Statcast Metrics and Throwing Progression as tabs underneath, in place of the two separate buttons." },
    { date: "2026-10-30", area: "Dashboard", title: "Pitchers' Statcast moves under Pitching", detail: "For pitchers, Statcast Metrics is now a tab inside Pitching, beside Pitching Assessment, Bullpens and Throwing (drawn as tabs now, not buttons). It adds their MLB arsenal from Baseball Savant: each pitch's shape and results, a spinning ball for each pitch on its real MLB spin axis and active spin, and the closest MLB comps for every pitch with how those pitches did." },
    { date: "2026-10-30", area: "Dashboard", title: "Bullpens: Edgertronic video for every pitch", detail: "Add a bullpen's Edgertronic video beside its TrackMan report: the clips the camera saves (one per pitch, matched in order) or one long video, which the dashboard splits at its cuts. Then a camera button on a pitch (in Every pitch, or on a dot you click on the charts) plays it, looped, with frame-by-frame and slow motion, and arrows to step through the pitches. A clip on the wrong pitch can be moved, with every one after it, from the player." },
    { date: "2026-10-29", area: "Dashboard", title: "Bullpen comps: are they good pitches?", detail: "Each MLB comp now shows how that pitch did in games: usage, whiff %, put-away %, xwOBA and run value per 100 pitches (Baseball Savant), shaded red for better than most of that pitch and blue for worse, with a line averaging the closest comps. Pitchers linked to MLB get their own game numbers beside the bullpen, and a new MLB arsenal section with every pitch they threw that season." },
    { date: "2026-10-29", area: "Dashboard", title: "Bullpens: pitches, averages or both", detail: "A switch over the movement and release charts shows every pitch with each type's average, just the pitches, or just the averages (labeled, so the arsenal's shape reads at a glance)." },
    { date: "2026-10-29", area: "Dashboard", title: "Bullpens: zoom in on a pitch's spin", detail: "Click a spinning ball to open it large, with pause, speed and pitcher or catcher view, and arrows to step through the arsenal. The balls now start from behind the pitcher, and the seams sit a little more open." },
    { date: "2026-10-29", area: "Dashboard", title: "Bullpen comps against MLB and DST", detail: "A Comps section on each bullpen: for every pitch type, its MLB percentile for velo, IVB, arm-side run, spin and release height (same pitch, same throwing hand, from Baseball Savant), and the closest MLB and DST pitchers by shape, with a match score." },
    { date: "2026-10-29", area: "Dashboard", title: "Throws and bats on player profiles", detail: "The ✎ beside a player's name now sets which hand he throws and bats with, shown in the profile header as B/T R/R. Players linked to MLB fill it in on their own." },
    { date: "2026-10-29", area: "Dashboard", title: "Bullpens: spin from either side, paused or slowed", detail: "The spinning balls can be paused, slowed (¼× to 2×) and seen from the catcher or from behind the pitcher, with the spin direction and tilt arrow right for each side. Sinkers and two-seamers spin with a two-seam orientation, everything else four-seam." },
    { date: "2026-10-29", area: "Dashboard", title: "Bullpens: pick out a pitch type", detail: "Above the movement and release charts, a key of the pitch types: click one to pick it out and the others dim, click more to add them, and Show all to clear. The release point chart is now the catcher's view (a right-hander releases on the left)." },
    { date: "2026-10-29", area: "Dashboard", title: "Bullpens: release point, VAA, spin and your own layout", detail: "Each bullpen now has a release point chart, an estimated vertical approach angle for every pitch (worked out from release, velo, IVB and where it crossed the plate), and a 3D baseball for each pitch type spinning on its real axis (its tilt, leaned by its gyro: 100% minus spin efficiency), with its spin, tilt, spin efficiency, gyro %, active spin and gyro spin. Click any pitch on the movement or release chart to retag it or take it out (Put back undoes it), switch the charts between this session and all sessions, and drag the report's sections into the order you like, half or full width." },
    { date: "2026-10-29", area: "Dashboard", title: "A Pitching tab for pitchers", detail: "A pitcher's profile has one Pitching tab with three parts: Pitching Assessment (moved from Assessments), Bullpens, and Throwing (the throwing programs on their plan with Open buttons, then their Throwing Progression)." },
    { date: "2026-10-29", area: "Dashboard", title: "Import TrackMan bullpens", detail: "Pitching › Bullpens › Import TrackMan PDF reads a TrackMan Pitching practice report: every pitch with its type, velo, spin, break, release and extension, the averages by pitch type, a movement plot, and velo by pitch type across sessions. Pitches TrackMan didn't tag can be tagged afterward, one at a time or several at once. The same import on a Pitching Assessment also fills its Pitch Movement table and Initial Velo: Mound." },
    { date: "2026-10-29", area: "Coach Mode", title: "Drag athletes into your order", detail: "Grab the ⋮⋮ beside a name on the board, in Team today or in Group Testing and drag it up or down (along the strip on a phone). The order sticks everywhere in Coach Mode, so the testing sheet runs in the order the group goes through." },
    { date: "2026-10-29", area: "Dashboard", title: "Take out a bad force plate test", detail: "On Performance Metrics, the ✕ at the end of a test row removes it (two people on the plates, a stumble). It comes off the graphs, the trends and the athlete's app, the Hawkin sync won't bring it back, and Removed tests under the table puts it back if you change your mind." },
    { date: "2026-10-29", area: "Phone app", title: "Steadier progress graphs", detail: "A tiny change (a body weight 0.02 lb lighter, say) no longer stretches to fill the graph and look like a big drop, and the numbers up the side always read differently instead of repeating." },
    { date: "2026-10-29", area: "Phone app", title: "Back to the program while the EDT clock runs", detail: "On an EDT block, \"▾ Back to the program\" (or a tap outside the timer) shrinks it to a bar across the top of the screen. The clock keeps running, and the bar has its own − and +1 set, so athletes can check their reps and weights without restarting. Open brings the full timer back; Done · log it logs the sets as before." },
    { date: "2026-10-29", area: "Dashboard", title: "Edit a player from their profile", detail: "The ✎ beside a player's name on their profile edits their name, jersey number, league, team and DST location, the same as the pencil on the roster." },
    { date: "2026-10-29", area: "Phone app", title: "Re-Ed is one daily routine", detail: "A re-education program is now built as one day. Athletes see it as \"Daily\" in their app every day, fresh each morning, for as long as the Re-Ed phase on their plan runs, or until it's changed." },
    { date: "2026-10-29", area: "Dashboard", title: "Scrap a player's program and start over", detail: "On a player's Programming tab, Scrap and start over deletes the program you were building for that phase and empties the phase, ready to build again or load a saved program. A shared template is only taken off the phase, never deleted." },
    { date: "2026-10-29", area: "Dashboard", title: "More from Kyle Kleeman: NFL Intensification v2", detail: "The other version of his NFL Intensification block (Lineman and Skill, 3 weeks, four days a week) is in Programs › Strength › NFL Intensification." },
    // ---- week of Oct 22-28, 2026 ----
    { date: "2026-10-28", area: "Dashboard", title: "Kyle Kleeman's NFL Intensification programs", detail: "Two new 3-week programs in Programs › Strength › NFL Intensification, one for linemen and one for skill players. Their Corrective lines pick from each athlete's own re-ed drills once the program is on a player's plan." },
    { date: "2026-10-28", area: "Program builder", title: "Re-Ed placeholders pick from the athlete's own drills", detail: "In a player's program, an exercise named Re-Ed, Corrective, Insert Re-Ed, Mobility Drill and the like gets a pick list of that player's re-ed drills, their current Re-Ed program first, or type in anything else. Choose this week only or every week after, and for more than one week the series opens across the weeks to set the sets and reps." },
    { date: "2026-10-28", area: "Dashboard", title: "What's new, in the top bar", detail: "Everything new in the dashboard, the program builder, Coach Mode and the athletes' app, week by week. A red dot shows when there's something you haven't seen, and the same list comes by email every Monday." },
    { date: "2026-10-28", area: "Program builder", title: "Table view is now the standard", detail: "Programs open as a spreadsheet: one row per exercise with Sets, Reps and Intensity cells. Tab, Enter and the arrow keys move between cells like Google Sheets. Boxes is still one click away, and your choice is remembered." },
    { date: "2026-10-28", area: "Program builder", title: "Copy and paste like a sheet", detail: "Drag across cells (or Shift+click) to highlight a block, then Ctrl+C, Ctrl+V, Ctrl+X or Delete. Rows copied from Google Sheets or Excel paste straight in, and a 1, 1, 2, 2 or A1, A2 column sets the supersets." },
    { date: "2026-10-28", area: "Program builder", title: "Color-coded blocks", detail: "A1, A2 and A3 share a color and an outline box, B gets the next color, and so on. Rows line up across the days, so every A2 sits level with the other days' A2." },
    { date: "2026-10-28", area: "Program builder", title: "Progress a day across the weeks", detail: "The green ↗ on a day (or a block) opens that day for every week side by side. Type in new sets, reps and percentages, or fill the later weeks in one step: same every week, intensity +2.5 / +5, reps -1 and more." },
    { date: "2026-10-28", area: "Program builder", title: "\"With sets 1–2\" for a changing partner", detail: "When the A2 exercise changes partway through A1's sets, keep A1 as one 4x5 and tag A2 \"with sets 1–2\" and A3 \"with sets 3–4\" instead of splitting it into A and B. The tissue compliance programs are already fixed this way." },
    { date: "2026-10-28", area: "Program builder", title: "Tempo, EDT and set weights", detail: "Tempo takes isos and ladders (*5* for a 5-second iso, 6-1 descending, 6-1-6 down and back up). EDT is its own setting with a minutes box. Intensity can be a weight: type 135 lb or 60 kg." },
    { date: "2026-10-28", area: "Program builder", title: "Add a column to every exercise at once", detail: "+ Column adds Tempo, Rest, Notes, Time, Distance, Speed or a box you name to a whole day (or every day of the week). A new day starts with just Sets, Reps and Intensity." },
    { date: "2026-10-28", area: "Program builder", title: "Re-Education programs", detail: "A new program type laid out in sections and series (Tissue Prep, Upper Body, Lower Body and Movement Re-Education) with sets, reps, a time and a weight for each drill. Build one from the Programs page." },
    { date: "2026-10-28", area: "Program builder", title: "Speed and throwing builders get the table too", detail: "Section titles in red tabs with the column titles under each one, every series boxed in its own color, undo and redo (Ctrl+Z), and copy and paste. Throwing days are colored by intensity: green Low, yellow Medium, red High." },
    { date: "2026-10-28", area: "Coach Mode", title: "Add a whole location at once", detail: "Pick a location (DST North, say) and tap + Add all to put everyone there on the board, then take off anyone who isn't in today." },
    { date: "2026-10-28", area: "Coach Mode", title: "Fold away the side bars", detail: "‹ Hide at the bottom of the athletes list, and the › at the top right for the day summary, give the program the whole screen. Coach Mode remembers what you closed." },
    { date: "2026-10-28", area: "Dashboard", title: "Refresh keeps your place", detail: "Reloading the page opens the same page, athlete, tab or program you were on, instead of starting over at the Team Overview." },
    { date: "2026-10-28", area: "Dashboard", title: "No more duplicate program copies", detail: "Editing a player's program no longer makes extra copies of it in the background." },
    { date: "2026-10-27", area: "Phone app", title: "Save or print the program and nutrition plan", detail: "Athletes can save their program (one day to a page, all its weeks across) and their nutrition plan (one section to a page) as a PDF, then share, save or print it from their phone." },
    { date: "2026-10-27", area: "Phone app", title: "Clearer prescriptions", detail: "Athletes see \"With sets 1–2\" on a changing superset partner, a set weight like \"135 lb\" beside the box, and tempos in place of notes on the iso work." },
    { date: "2026-10-27", area: "Phone app", title: "Water: type your own amount", detail: "Besides +8, +16 and the rest, an \"Other oz\" box takes any amount." },
    { date: "2026-10-27", area: "Dashboard", title: "Bigger food database", detail: "224 foods from the DST Food Database & Macro Tracker were added for the food log. A food a coach adds goes into everyone's database; one an athlete adds stays theirs." },
    { date: "2026-10-27", area: "Dashboard", title: "Kyle Kleeman's programs", detail: "His 10-week speed program and three strength programs are in the Programs library, listed as written by Kyle Kleeman." },
  ];

  const api = { WHATS_NEW, AREAS };
  if (typeof module !== "undefined" && module.exports) module.exports = api;
  else root.WhatsNew = api;
})(typeof window !== "undefined" ? window : this);
